namespace ghidra.app.plugin.core.datamgr.actions;



using docking;
using docking.action;
using docking.action;
using docking.widgets.tree;
using docking.widgets.tree;
using ghidra.app.plugin.core.datamgr;
using ghidra.app.plugin.core.datamgr;
using ghidra.app.plugin.core.datamgr.tree;

/**
 * Renames objects in the datatypes tree if they support being renamed
 */
public class RenameAction : DockingAction {

	public RenameAction(DataTypeManagerPlugin plugin) : base("Rename", plugin.getName())
    {

		setPopupMenuData(new MenuData(new string[] { "Rename" }, null, "Edit"));
	}

	/* @Override */
	public bool isAddToPopup(ActionContext context) {
		GTreeNode node = getSelectedNode(context);
		if (node == null || node is ArchiveRootNode || node is DataTypeStoreNode ||
			node is InvalidArchiveNode) {
			return false;
		}
		return true;
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		GTreeNode node = getSelectedNode(context);
		return node != null && node.isEditable();
	}

	private GTreeNode getSelectedNode(ActionContext context) {
		if (!(context is DataTypesActionContext)) {
			return null;
		}

		object contextObject = context.getContextObject();
		GTree gtree = (GTree) contextObject;
		TreePath[] selectionPaths = gtree.getSelectionPaths();
		if (selectionPaths.length != 1) {
			return null;
		}

		GTreeNode node = (GTreeNode) selectionPaths[0].getLastPathComponent();
		return node;
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		DataTypeArchiveGTree gtree = (DataTypeArchiveGTree) context.getContextObject();
		rename(gtree);
	}

	void rename(DataTypeArchiveGTree tree) {
		TreePath path = tree.getSelectionPath();
		GTreeNode node = (GTreeNode) path.getLastPathComponent();
		tree.startEditing(node);
	}

}
